def canon(x):return json.dumps(x,sort_keys=True,separators=(',',':')).encode()
def sha(x):return hashlib.sha256(x).hexdigest()
@functools.lru_cache(None)
def T(x):
    b=[(x>>j)&1 for j in range(x.bit_length()+2)]
    return sum((b[j]^((b[j-1] if j>=1 else 0)|(b[j-2] if j>=2 else 0)))<<j for j in range(len(b)))
def A(x):return T(x)>>2
def G(g,x):return T(x) if g=='t' else T(x)^1 if g=='u' else T(2*x+1)>>1
S='tupp';L='tup'
def I(x):return int(x%64 in [0,5])
def gate(x):return 'u' if x%16==7 else 't' if x%16==11 else None
def F(x):
    g=gate(x);assert g;return G(g,G('p',x>>2))
def omega(x,g):return int((x%16==0 and g=='t') or (x%16==1 and g=='u'))
def wordstate(root,w):
    x=root;pref=[x];costs=[]
    for g in w:costs.append(omega(x,g));x=G(g,x);pref.append(x)
    return x,pref,costs
def H(root,w):return ''.join(S[x%4] for x in wordstate(root,w)[1][1:])
@functools.lru_cache(None)
def powerA(x,r):
    for _ in range(r):x=A(x)
    return x
def J(x):return I(A(x))+I(x>>2)
def D(x,s):return sum(I(powerA(x>>(2*d),s-1-d)) for d in range(s))
def beta(xs,branches,s):
    cost=0
    for t in range(1,s+1):
        old=powerA(xs[t-1],s-t+1)
        letter=branches[t-1] if t==s else S[powerA(xs[t],s-t-1)%4]
        cost+=omega(old,letter)
    return cost
@functools.lru_cache(None)
def forced(x,maxsteps):
    xs=[x];letters=''
    for _ in range(maxsteps):
        g=gate(x)
        if g is None:break
        letters+=g;x=F(x);xs.append(x)
    return xs,letters
