for phase,root in [('p',3),('u',1)]:
    level=[('',root)]
    for n in range(9):
        if n<=4:
            front=sorted({x for _,x in level});assert all(not I(x) for x in front)
            assert {A(x) for x in front}<=set(front);base[phase+str(n+1)]=front
        for w,x in level:
            word_count+=1;current=w;original_pref=wordstate(root,w)[1]
            xs,branches=forced(x,n+4);fw=w;forced_words={0:w}
            for age in range(1,min(n+3,len(branches))+1):
                fw=H(root,fw)+branches[age-1];assert wordstate(root,fw)[0]==xs[age];forced_words[age]=fw
            for s in range(1,n+4):
                current=H(root,current);end,pref,costs=wordstate(root,current)
                assert end==powerA(x,s)
                expect=[I(powerA(v,s-1)) for v in original_pref[1:]]
                assert costs==expect and not any(costs[:4]);identity_positions+=n
                if s<max(1,n-4):continue
                C=sum(costs);ds=D(x,s);phantom=max(s-n-1,0)
                assert C==ds-phantom
                q=x% (1<<(2*s+4));assert ds==D(q,s)
                rowhash.update(canon([phase,n,w,x,s,C,ds,phantom])+b'\n');cases+=1
                if len(branches)<s+1:continue
                sig=branches[:s+1];actual=wordstate(root,forced_words[s]);W=sum(actual[2]);born=beta(xs,branches,s)
                assert W==C+born
                qxs,qsig=forced(q,s+1);assert qsig==sig and beta(qxs,qsig,s)==born
                assert W+phantom==D(q,s)+beta(qxs,qsig,s)
                boundary=[{'t':t,'quotient_mod256':(xs[t]>>(2*(s-t-2)))%256,'J':J(xs[t]>>(2*(s-t-2)))} for t in range(s-1)]
                assert sum(t['J'] for t in boundary)==W+phantom
                key=(s,sig)
                if key not in groups:groups[key]={'s':s,'branches':sig,'q':q,'W_plus_padding':W+phantom,'D':ds,'beta':born,'boundary_terms':boundary,'phase_lengths':set(),'endpoints':set(),'histories':0,'examples':{}}
                group=groups[key];assert group['boundary_terms']==boundary
                assert (group['q'],group['W_plus_padding'],group['D'],group['beta'])==(q,W+phantom,ds,born)
                group['phase_lengths'].add((phase,n));group['endpoints'].add(x);group['histories']+=1
                group['examples'].setdefault(phase+str(n),{'phase':phase,'n':n,'word_from_zero':phase+w,'endpoint':x,'s':s,'C':C,'W':W,'padding':phantom})
                fhash.update(canon([phase,n,w,x,s,sig,C,W,born,phantom])+b'\n');forced_cases+=1
        if n<8:level=[(w+g,G(g,x)) for w,x in level for g in L]
